    local function VM_II0l(d, k, m)
        local R_IIOOOO0l = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IIOOOO0l, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IIOOOO0l)
    end

    -- Execution Guard
    local F_1IOO = loadstring(VM_II0l(B_11l0O, 15, 3))
    if F_1IOO then
        F_1IOO(...)
